import numpy as np
def find_windows(M, minsz=16):
    Hh,Ww=M.shape; out=[]
    for h in range(4,12):
        for w in range(4,12):
            if h*w<minsz: continue
            for r0 in range(Hh-h+1):
                for c0 in range(Ww-w+1):
                    sub=M[r0:r0+h,c0:c0+w]
                    u,c=np.unique(sub,return_counts=True)
                    m=int(u[c.argmax()])
                    if c.max()==sub.size and m!=8 and sub.size>=minsz:
                        out.append((m,h,w,r0,c0,int(sub.size)))
    return sorted(out,key=lambda x:-x[5])
